static const char kk_fp32_flush_msl[] = "\n// Rounding can promote a mathematically subnormal result to FLT_MIN. Native\n// FTZ on Apple GPUs can lose that boundary result before rounding. Repair only\n// zero results with nonzero finite operands; ordinary nonzero results stay native.\ninline float kk_ftz_value(float x)\n{\n   uint u = as_type<uint>(x);\n   return as_type<float>((u & 0x7f800000u) ? u : (u & 0x80000000u));\n}\n__attribute__((noinline)) float kk_ftz_mul_slow(float a, float b)\n{\n   return kk_ftz_value(kk_dp_mul(kk_ftz_value(a), kk_ftz_value(b)));\n}\ninline float kk_ftz_mul(float a, float b)\n{\n   float r = a * b;\n   if (kk_dp_abs(r) == 0u) {\n      uint am = kk_dp_abs(a), bm = kk_dp_abs(b);\n      if (am >= 0x800000u && bm >= 0x800000u &&\n          am < 0x7f800000u && bm < 0x7f800000u)\n         return kk_ftz_mul_slow(a, b);\n   }\n   return r;\n}\n__attribute__((noinline)) float kk_ftz_fma_slow(float a, float b, float c)\n{\n   return kk_ftz_value(kk_dp_fma(kk_ftz_value(a), kk_ftz_value(b), kk_ftz_value(c)));\n}\ninline float kk_ftz_fma(float a, float b, float c)\n{\n   float r = precise::fma(a, b, c);\n   if (kk_dp_abs(r) == 0u) {\n      uint am = kk_dp_abs(a), bm = kk_dp_abs(b);\n      if (am >= 0x800000u && bm >= 0x800000u &&\n          am < 0x7f800000u && bm < 0x7f800000u)\n         return kk_ftz_fma_slow(a, b, c);\n   }\n   return r;\n}\n__attribute__((noinline)) float kk_ftz_div_slow(float a, float b)\n{\n   return kk_ftz_value(kk_dp_div(kk_ftz_value(a), kk_ftz_value(b)));\n}\ninline float kk_ftz_div(float a, float b)\n{\n   float r = a / b;\n   if (kk_dp_abs(r) == 0u) {\n      uint am = kk_dp_abs(a), bm = kk_dp_abs(b);\n      if (am >= 0x800000u && bm >= 0x800000u &&\n          am < 0x7f800000u && bm < 0x7f800000u)\n         return kk_ftz_div_slow(a, b);\n   }\n   return r;\n}\n";
